package bitcoinlib

import (
	"bytes"
	"encoding/hex"
	"github.com/btcsuite/btcd/wire"
	"testing"
)

func TestCalculateP2WSHVSize(t *testing.T) {
	t.Log(CalculateP2WSHVSize(1, 2))
}

func TestCalculateP2WSHVSizeV2(t *testing.T) {
	inputCount, outputCount := 2, 2

	t.Log(CalculateP2WSHVSize(inputCount, outputCount))
	t.Log(CalculateP2WSHVSizeV2(inputCount, outputCount, 2, 3, 104))
}

func TestC(t *testing.T) {
	bz, _ := hex.DecodeString("")
	tx := wire.MsgTx{}
	if err := tx.Deserialize(bytes.NewReader(bz)); err != nil {
		t.Log(err)
	}
	t.Log(tx.SerializeSize())         //722
	t.Log(tx.SerializeSizeStripped()) //178
}
